<script setup lang="ts">
import{computed}from'vue';import{useSession}from'../session';import{customerPortal}from'../portal';import{actorKey}from'../ticket-work';import{retainedReplyDrafts}from'../ticket-supplement-work';import type{TicketDetail}from'../ticket-api';import SupplementFiles from'./SupplementFiles.vue';
const props=defineProps<{ticket:TicketDetail}>(),auth=useSession();const drafts=computed(()=>customerPortal&&auth.identity?.identityType==='CUSTOMER'?retainedReplyDrafts(actorKey(auth),props.ticket.id).filter(d=>props.ticket.readOnly?d.roundId===props.ticket.roundId:d.roundId!==props.ticket.roundId):[]);
</script>
<template><section v-if="drafts.length" class="panel retained-round-drafts"><h2>旧轮本标签页补充草稿（仅历史）</h2><p>以下是本浏览器保留的原File、摘要及上传/回复UUID，未确认上传不表示已提交回复。它们不能迁移为当前轮回复或证据，也不会自动重发或丢弃。</p><article v-for="d in drafts" :key="d.key" class="record-entry"><p>原轮 {{d.roundId}} · 原回复UUID {{d.key}}</p><template v-if="ticket.readOnly"><p style="white-space:pre-wrap">未确认草稿（非已提交回复）：{{d.body}}</p><SupplementFiles :draft="d" :ticket="ticket" read-only/></template><template v-else><p v-for="f in d.files" :key="f.uploadId">{{f.file.name}} · {{f.state}} · 原上传UUID {{f.uploadId}}</p><RouterLink :to="`/tickets/${ticket.id}/rounds/${d.roundId}`">在原轮只读查询草稿与原上传</RouterLink></template></article></section></template>
